def transform(grid):
    R, C = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    # find connected components of background (6) not touching border
    seen = [[False]*C for _ in range(R)]
    from collections import deque
    for i in range(R):
        for j in range(C):
            if grid[i][j] == 6 and not seen[i][j]:
                comp = []
                q = deque([(i, j)])
                seen[i][j] = True
                touches = False
                while q:
                    x, y = q.popleft()
                    comp.append((x, y))
                    if x in (0, R-1) or y in (0, C-1):
                        touches = True
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < R and 0 <= ny < C and not seen[nx][ny] and grid[nx][ny] == 6:
                            seen[nx][ny] = True
                            q.append((nx, ny))
                if not touches:
                    # find surrounding shape color
                    shape = None
                    for x, y in comp:
                        for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                            nx, ny = x+dx, y+dy
                            if 0 <= nx < R and 0 <= ny < C and grid[nx][ny] != 6:
                                shape = grid[nx][ny]
                    fill = 2 if (shape % 2 == 0) else 7
                    for x, y in comp:
                        g[x][y] = fill
    return g
